import 'package:flutter/services.dart';

/// Host must obtain explicit authorization before persisting a new credential.
/// IDs are region-scoped opaque credential references: region + ':' +
/// 64 lowercase SHA-256 hex characters, generated by the host service.
class MacMiniMaxKeychain {
  static const _channel = MethodChannel('com.sailingloong.loongpass/files');
  static final _id = RegExp(r'^(cn|global):[0-9a-f]{64}$');

  static void _validateId(String id) {
    if (_id.firstMatch(id)?.end != id.length) {
      throw const MiniMaxKeychainException('invalid_arguments');
    }
  }

  static bool _validToken(String token) => token.isNotEmpty &&
      token.length <= 16384 &&
      token.codeUnits.every((c) => c >= 33 && c <= 126);

  Future<T?> _invoke<T>(String method, [Map<String, Object>? arguments]) async {
    try {
      return await _channel.invokeMethod<T>(method, arguments);
    } on PlatformException catch (error) {
      const codes = {'invalid_arguments', 'keychain_locked',
        'keychain_unavailable', 'invalid_credential', 'journal_unavailable'};
      throw MiniMaxKeychainException(codes.contains(error.code)
          ? error.code : 'keychain_unavailable');
    } catch (_) {
      // Never propagate platform messages/details or token-bearing arguments.
      throw const MiniMaxKeychainException('keychain_unavailable');
    }
  }

  Future<String?> read(String id) async {
    _validateId(id);
    final token = await _invoke<String>('minimaxKeychainRead', {'id': id});
    if (token != null && !_validToken(token)) {
      throw const MiniMaxKeychainException('invalid_credential');
    }
    return token;
  }

  Future<void> write(String id, String accessToken) async {
    _validateId(id);
    if (!_validToken(accessToken)) {
      throw const MiniMaxKeychainException('invalid_credential');
    }
    await _invoke<void>('minimaxKeychainWrite',
        {'id': id, 'accessToken': accessToken});
  }

  /// Explicit single-account deletion only; never called automatically here.
  Future<void> delete(String id) async {
    _validateId(id);
    await _invoke<void>('minimaxKeychainDelete', {'id': id});
  }

  /// Nonsecret metadata only. Caller must flush its file before syncJournal.
  Future<String> prepareJournal() async {
    final path = await _invoke<String>('prepareMiniMaxJournal');
    if (path == null || !path.startsWith('/') || path.contains('\u0000')) {
      throw const MiniMaxKeychainException('journal_unavailable');
    }
    return path;
  }

  Future<void> syncJournal() async {
    await _invoke<void>('syncMiniMaxJournal');
  }
}

class MiniMaxKeychainException implements Exception {
  final String code;
  const MiniMaxKeychainException(this.code);
  @override
  String toString() => 'MiniMaxKeychainException($code)';
}
